<script setup>
defineProps({ app: { type: Object, required: true } })
const splitLines = value => value.split('\n').map(line => line.trim()).filter(Boolean)
const addContainer = group => group.push({ name: '', image: '', command: [], args: [], env: [] })
</script>

<template>
  <fieldset class="app-fields"><legend>主容器环境变量</legend><div v-for="(item, index) in app.env" :key="index" class="env-row"><label>名称<input v-model.trim="item.name" required placeholder="例如 APP_MODE" /></label><label>值<input v-model="item.value" /></label><button type="button" class="text danger" :aria-label="`删除第 ${index + 1} 个主容器环境变量`" @click="app.env.splice(index, 1)">删除</button></div><button type="button" class="light" @click="app.env.push({ name: '', value: '' })">＋ 添加环境变量</button></fieldset>
  <fieldset v-for="[key, title] in [['containers', '附加容器'], ['initContainers', '初始化容器']]" :key="key" class="app-fields"><legend>{{ title }}</legend><div v-for="(container, index) in app[key]" :key="index" class="container-card"><div class="container-head"><strong>{{ container.name || `${title} ${index + 1}` }}</strong><button type="button" class="text danger" @click="app[key].splice(index, 1)">删除容器</button></div><div class="container-grid"><label>容器名称<input v-model.trim="container.name" required placeholder="例如 helper" /></label><label>镜像<input v-model.trim="container.image" required placeholder="registry.example.com/helper:latest" /></label><label>命令（每行一个参数）<textarea :value="(container.command || []).join('\n')" rows="2" @input="container.command = splitLines($event.target.value)" /></label><label>启动参数（每行一个）<textarea :value="(container.args || []).join('\n')" rows="2" @input="container.args = splitLines($event.target.value)" /></label></div><div v-for="(item, envIndex) in container.env" :key="envIndex" class="env-row"><label>变量名称<input v-model.trim="item.name" required /></label><label>值<input v-model="item.value" /></label><button type="button" class="text danger" :aria-label="`删除第 ${envIndex + 1} 个环境变量`" @click="container.env.splice(envIndex, 1)">删除</button></div><button type="button" class="light" @click="container.env.push({ name: '', value: '' })">＋ 添加环境变量</button></div><button type="button" class="light" @click="addContainer(app[key])">＋ 添加{{ title }}</button></fieldset>
</template>

<style scoped>
.app-fields{border:1px solid var(--color-border-2,#e5e6eb);border-radius:2px;padding:14px;margin:0 0 20px;min-width:0}.app-fields legend{color:var(--color-text-2,#4e5969);font-size:13px}.app-fields>.light{margin-top:4px}.env-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;align-items:end;gap:10px;margin-bottom:12px}.container-card{padding:14px;border:1px solid var(--color-border-2,#e5e6eb);margin-bottom:14px;min-width:0}.container-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px}.container-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}.env-row>*{min-width:0}@media(max-width:600px){.env-row,.container-grid{grid-template-columns:minmax(0,1fr)}.env-row .text{justify-self:start}.container-card{padding:10px}}
</style>
